def apply(inputs, premises):
    checked_dimensions = []
    checked_weights = []
    personal_used = False
    carry_on_used = False
    for i in range(len(inputs["item_dimension_sums"])):
        if inputs["personal_item_eligible"][i] and not personal_used:
            personal_used = True
        elif inputs["carry_on_eligible"][i] and not carry_on_used:
            carry_on_used = True
        else:
            checked_dimensions = checked_dimensions + [inputs["item_dimension_sums"][i]]
            checked_weights = checked_weights + [inputs["item_weights"][i]]
    fee_total = 0
    for i in range(len(checked_dimensions)):
        if i == 0:
            base_fee = inputs["first_checked_bag_fee"]
        elif i == 1:
            base_fee = inputs["second_checked_bag_fee"]
        elif i == 2:
            base_fee = inputs["third_checked_bag_fee"]
        else:
            base_fee = inputs["fourth_plus_checked_bag_fee"]
        oversize_fee = 0
        if checked_dimensions[i] > 62:
            if checked_dimensions[i] <= 65:
                oversize_fee = inputs["oversize_63_to_65_fee"]
            else:
                oversize_fee = inputs["oversize_over_65_fee"]
        overweight_fee = 0
        if checked_weights[i] > 50 and checked_weights[i] <= 53:
            overweight_fee = inputs["overweight_51_to_53_fee"]
        elif checked_weights[i] > 53 and checked_weights[i] <= 70:
            overweight_fee = inputs["overweight_54_to_70_fee"]
        elif checked_weights[i] > 70:
            overweight_fee = inputs["overweight_over_70_fee"]
        if premises["use_higher_excess_fee"]:
            excess_fee = max(oversize_fee, overweight_fee)
        else:
            excess_fee = oversize_fee + overweight_fee
        fee_total = fee_total + base_fee + excess_fee
    answer = int(inputs["ticket_price"] + fee_total)
    return {"answer": answer}

